\label{thm:discontinuity}
For any $0\le \rho \le+\infty$ there is a $\mathbb{Z}^2$-action $(X,\mathbb{Z}^2,T)$ such that
\begin{itemize}
\item if $\vec{v}\in\{(-1,0),(1,0)\}$ then $\operatorname{mdim}(X,T,\langle\vec{v}\rangle^{\perp})=\rho$;
\item if $\vec{v}\in\mathbb{S}\setminus\{(-1,0),(1,0)\}$ then $\operatorname{mdim}(X,T,\langle\vec{v}\rangle^{\perp})=0$.
\end{itemize}

\label{lem:orderclosedcover}
Let $X$ be a compact metric space and $\alpha$ a finite open cover of $X$. Then the following statements hold:\begin{enumerate}\item$\mathcal{D}(\alpha)=\min_\beta\operatorname{ord}(\beta)$, where $\beta$ runs over all finite closed covers of $X$ refining $\alpha$;
\item$\mathcal{D}(\alpha)\le l$ if and only if there is a compact metric space $P$ of topological dimension $l$ and a continuous mapping $f\colon X\to P$ which is $\alpha$-compatible \textup(i.e. there exists a finite open cover $\beta$ of $P$ such that $f^{-1}(\beta)$ refines $\alpha$\textup).
\end{enumerate}

\label{prop:contexpansive}
(1) There is $\delta>0$ such that if $A\in C(X)$ and $N\ge1$ satisfy the condition $c\le\max\{\operatorname{diam} T^n(A):n\in[-N,N]^k\}\le2c$ then $\max\{\operatorname{diam} T^n(A):n\in\partial[-N,N]^k\}>\delta$.

(2) For any $\epsilon>0$ there is $m=m(\epsilon)>0$ such that if $A\in C(X)$ satisfies the condition $\max\{\operatorname{diam} T^n(A):n\in[-m,m]^k\}\le2c$ then $\operatorname{diam} A<\epsilon$.

(1) Suppose that the statement is false. There exist $\{A_i\}_{i\in\mathbb{N}}\subset C(X)$ and $\{N_i\}_{i\in\mathbb{N}}\subset\mathbb{N}$ satisfying that
\begin{equation}\label{equ:diampart}
c\le\max\{\operatorname{diam} T^n(A_i):n\in[-N_i,N_i]^k\}\le2c,\quad\forall i\in\mathbb{N};
\end{equation}
\begin{equation}\label{equ:diampartial}
\max\{\operatorname{diam} T^n(A_i):n\in\partial[-N_i,N_i]^k\}\le1/i,\quad\forall i\in\mathbb{N}.
\end{equation}
Suppose that the sequence $\{N_i\}_{i\in\mathbb{N}}\subset\mathbb{N}$ is bounded by some $0<M<+\infty$. We may assume (by the compactness of $C(X)$) that $\{A_i\}_{i\in\mathbb{N}}$ converges to some $A\in C(X)$. Hence \eqref{equ:diampart} and \eqref{equ:diampartial} lead to a contradiction for $\operatorname{diam} T^n(A)$ for some $n\in[-M,M]^k$. So we assume without loss of generality (by taking a subsequence) that $N_i\to+\infty$ as $i\to\infty$.

We take a sequence $\{n_i\}_{i\in\mathbb{N}}$, with $n_i\in [-N_i,N_i]^k$ and such that $\operatorname{diam} T^{n_i}(A_i) =  \max \{\operatorname{diam}  T^n(A_i):n\in[-N_i,N_i]^k\}$ for all $i\in\mathbb{N}$. We claim that the distance between $n_i$ and $\partial[-N_i,N_i]^k$ goes to $+\infty$ as $i\to\infty$. In fact, if this assertion is not true, then there exists $l\in\mathbb{N}$ such that $n_i\notin[-N_i+l,N_i-l]^k$ for infinitely many $i\in\mathbb{N}$. For all these $i\in\mathbb{N}$ we write $n_i=p_i+q_i$ with $p_i\in[-l,l]^k$ and $q_i\in\partial[-N_i,N_i]^k$. We take $\epsilon>0$ sufficiently small such that $\operatorname{diam} T^n(A)<c/2$ for all $n\in[-l,l]^k$ whenever $\operatorname{diam} A<\epsilon$. It follows from \eqref{equ:diampartial} that $\operatorname{diam} T^{n_i}(A_i)=\operatorname{diam} T^{p_i}(T^{q_i}(A_i))<c/2$ for all sufficiently large $i$ (with $1/i<\epsilon$), which contradicts \eqref{equ:diampart}, and thus proves the claim.

We assume (by choosing a subsequence) that $T^{n_i}(A_i)$ tends to $B\in C(X)$ as $i\to\infty$. For any given $m\in\mathbb{Z}^k$ there is some $i_0\in\mathbb{N}$ such that $m+n_i\in[-N_i,N_i]^k$, for all $i\ge i_0$, which, together with \eqref{equ:diampart}, implies $\operatorname{diam} T^{m+n_i}(A_i)\le\max\{\operatorname{diam} T^n(A_i):n\in[-N_i,N_i]^k\}\le2c$. Letting $i\to\infty$ in the above inequality we obtain $\operatorname{diam} T^m(B)\le2c$. Since $B$ is nondegenerate, this is a contradiction.

(2) Suppose that the statement is false. There exist $\epsilon_0>0$ and a sequence $\{A_i\}_{i\in\mathbb{N}}\subset C(X)$ such that $\max\{\operatorname{diam} T^n(A_i):n\in[-i,i]^k\}\le2c$ and $\operatorname{diam} A_i\ge\epsilon_0$ for all $i\in\mathbb{N}$. Choose a subsequence of $\{A_i\}_{i\in\mathbb{N}}$ tending to some $A\in C(X)$. Clearly, $\operatorname{diam} T^n(A)\le2c$ for all $n\in\mathbb{Z}^k$, and $\operatorname{diam} A\ge\epsilon_0$. This is a contradiction.

Let $\delta>0$ be a constant introduced in Lemma \ref{prop:contexpansive} (1). Choose a finite open cover $\mathcal{U}=\{U_1,\dots,U_L\}$ of $X$ with $\operatorname{mesh}(\mathcal{U},d)<\delta/2$. For each $N\ge1$ we let $\mathcal{U}_N$ be an open cover of $X$ defined by $\mathcal{U}_N=\bigvee_{u\in\partial[-N,N]^k}T^{-u}\mathcal{U}$. By Lemma \ref{lem:subadditivedegree}
\begin{equation}\label{equ:boundedorder}
\mathcal{D}(\mathcal{U}_N)\le|\partial[-N,N]^k|\cdot\mathcal{D}(\mathcal{U})\le2^k(2N+1)^{k-1}L,\quad\forall N\ge1.
\end{equation}
By Lemma \ref{lem:orderclosedcover}, for each $N\ge1$ there is a finite closed cover $\mathcal{V}_N$ of $X$, which refines $\mathcal{U}_N$ and which satisfies $\operatorname{ord}(\mathcal{V}_N)=\mathcal{D}(\mathcal{U}_N)$. For every $V\in\mathcal{V}_N$ we denote by $\mathcal{C}_V$ the set of all connected components of $V$. We set $\mathcal{C}_N=\{C\subset V:V\in\mathcal{V}_N,C\in\mathcal{C}_V\}$ and note that the sets in $\mathcal{C}_V$ are pairwise disjoint. The set $\mathcal{C}_N$ is a closed (not necessarily finite) cover of $X$, which refines $\mathcal{V}_N$ and satisfies $\operatorname{ord}(\mathcal{C}_N)=\operatorname{ord}(\mathcal{V}_N)$.
\newline\textsf{Claim 1.}
For every $N\ge1$ we have $\operatorname{mesh}(\mathcal{C}_N,d^T_{[-N,N]^k})<2c$.
\newline\textit{Proof of Claim 1.}
If $\operatorname{mesh}(\mathcal{C}_N,d^T_{[-N,N]^k})\ge2c$ for some $N\ge1$, then there exists $C\in\mathcal{C}_N$ such that $\max\{\operatorname{diam} T^n(C):n\in[-N,N]^k\}\ge2c$ which implies that $d^T_{[-N,N]^k}(x,y)\ge2c$ for some $x,y\in C$. We assume $C\in\mathcal{C}_V$ for some $V\in\mathcal{V}_N$. By Lemma \ref{lem:continuumarc}, there is a continuous mapping $\kappa\colon [0,1]\to C(V)$ satisfying $\kappa(0)=\{x\}$, $\kappa(1)=C$, and $\kappa(s)\subset\kappa(t)$ whenever $0\le s\le t\le1$. We define a continuous mapping $F\colon [0,1]\to[0,+\infty)$ by sending $t$ to $\max\{\operatorname{diam} T^n(\kappa(t)):n\in[-N,N]^k\}$. Clearly, $F(0)=0$ and $F(1)\ge2c$. So there is some $0<t_0<1$ with $F(t_0)=3c/2$. By Lemma \ref{prop:contexpansive} (1) we get $\max\{\operatorname{diam} T^n(\kappa(t_0)):n\in\partial[-N,N]^k\}>\delta$ and hence $\max\{\operatorname{diam} T^n(C):n\in\partial[-N,N]^k\}>\delta$. However, since $\mathcal{C}_N$ refines $\mathcal{U}_N$ and since $\operatorname{mesh}(\mathcal{U}_N,d_{\partial[-N,N]^k}^T)<\delta/2$, we have $\max\{\operatorname{diam} T^n(C):n\in\partial[-N,N]^k\}<\delta/2$, a contradiction. This shows Claim 1.
\newline\textsf{Claim 2.}
For every $N\ge1$ there exists a finite closed cover $\mathcal{W}_N$ of $X$ satisfying that $\operatorname{mesh}(\mathcal{W}_N,d^T_{[-N,N]^k})<2c$ and $\operatorname{ord}(\mathcal{W}_N)=\operatorname{ord}(\mathcal{V}_N)$.
\newline\textit{Proof of Claim 2.}
We fix $N\ge1$. We take an arbitrary $V\in\mathcal{V}_N$ for the moment. By Claim 1, $\operatorname{mesh}(\mathcal{C}_V,d^T_{[-N,N]^k})<2c$. Applying Lemma \ref{lem:decreasingclopen} to each connected component $C$ of $V$ we find a clopen subset $F_C\supset C$ of $V$, whose diameter is strictly smaller than $2c$ with respect to $d^T_{[-N,N]^k}$. So we obtain a clopen cover $\{F_C:C\in\mathcal{C}_V\}$ of $V$. Since $V$ is compact, there is a finite subcover $\{F_{C_1},F_{C_2},\dots,F_{C_{i(V)}}\}$ of $\{F_C:C\in\mathcal{C}_V\}$. We set $W_1^V=F_{C_1}$, $W_2^V=F_{C_2}\setminus F_{C_1}$, $\dots$, $W_{i(V)}^V=F_{C_{i(V)}}\setminus\cup_{j=1}^{i(V)-1}F_{C_j}$. It follows that $\{W_1^V,W_2^V,\dots,W_{i(V)}^V\}$ is a finite closed cover of $V$ satisfying that $W_s^V\cap W_t^V=\emptyset$ for all $1\le s<t\le i(V)$. Thus, we know that $\mathcal{W}_N=\{W_j^V:1\le j\le i(V),V\in\mathcal{V}_N\}$ is a finite closed cover of $X$. This shows Claim 2.
\newline Now by \eqref{equ:boundedorder} and noting that $\operatorname{ord}(\mathcal{W}_N)\le\mathcal{D}(\mathcal{U}_N)$ we finish the proof of the lemma.
